  ('s1-airplane-parts.flaps.c2', 'opt-1', 'A minimum altitude above the ground', false),
  ('s1-airplane-parts.flaps.c2', 'opt-4', 'A maximum speed for flap extension, published for your airplane', true),
  ('s1-airplane-parts.flaps.c2', 'opt-3', 'A limit on how many times they may be used per flight', false),
