  ('s1-airplane-parts.major-components.c2', 'opt-3', 'The horizontal stabilizer with the elevator, and the vertical stabilizer with the rudder', true),
  ('s1-airplane-parts.major-components.c2', 'opt-1', 'The ailerons and the flaps', false),
  ('s1-airplane-parts.major-components.c2', 'opt-2', 'The landing gear and its fairings', false),
  ('s1-airplane-parts.major-components.c2', 'opt-4', 'The propeller and its spinner', false),
  ('s1-airplane-parts.major-components.c3', 'opt-4', 'Because the correct name is required before a flight may be cancelled', false),
  ('s1-airplane-parts.major-components.c3', 'opt-2', 'So you can describe it precisely to your instructor or a mechanic, and it can be found and assessed', true),
