  ('s1-airplane-parts.major-components.c3', 'opt-3', 'It does not matter — pointing at it is enough', false),
  ('s1-airport-ramp.runway-numbering.c1', 'opt-2', 'East', false),
  ('s1-airport-ramp.runway-numbering.c1', 'opt-4', 'West — the number is the magnetic heading with the last digit dropped', true),
  ('s1-airport-ramp.runway-numbering.c1', 'opt-1', 'North', false),
  ('s1-airport-ramp.runway-numbering.c1', 'opt-3', 'It depends on the airport; the numbers are assigned in order', false),
  ('s1-airport-ramp.runway-numbering.c2', 'opt-3', '19', false),
