  ('s1-airport-ramp.markings-and-signs.c2', 'opt-1', 'A closed taxiway marking', false),
  ('s1-airport-ramp.markings-and-signs.c2', 'opt-3', 'A marking showing where to park', false),
  ('s1-airport-ramp.markings-and-signs.c3', 'opt-1', 'Keep taxiing until you recognise something', false),
