  ('s1-airport-ramp.markings-and-signs.c3', 'opt-3', 'Stop where you are, and ask for progressive taxi instructions', true),
  ('s1-airport-ramp.markings-and-signs.c3', 'opt-2', 'Follow the airplane ahead of you', false),
  ('s1-airport-ramp.hold-short.c1', 'opt-4', 'Stop before the holding position marking and do not cross it until cleared', true),
  ('s1-airport-ramp.hold-short.c1', 'opt-2', 'Cross the runway as quickly as you can', false),
  ('s1-airport-ramp.hold-short.c1', 'opt-1', 'Slow down, and continue if the runway looks clear', false),
  ('s1-airport-ramp.hold-short.c1', 'opt-3', 'Stop on the runway and wait there', false),
